function a2bSecKeys(s){ var ks = [s.perm].concat(s.perms || []); (s.tabs || []).forEach(function(t){ [].concat(t.perm || []).forEach(function(k){ ks.push(k); }); }); var o = []; ks.forEach(function(k){ if(k && o.indexOf(k) < 0) o.push(k); }); return o; }
