  var inc = a2bCard(Le('What is inside every backup', 'প্রতিটা ব্যাকআপে যা থাকে'), Le('Locked with your public key; only your recovery key opens it', 'আপনার পাবলিক কী দিয়ে লক; শুধু আপনার রিকভারি কী খোলে'), [['Database', 'ডাটাবেস'], ['Photos, media and generated files', 'ছবি, মিডিয়া আর তৈরি করা ফাইল'], ['Settings and every secret', 'সেটিং আর সব গোপন চাবি'], ['Code at that version', 'সেই সময়ের কোড'], ['Docs bundle with the commit', 'ডকুমেন্ট (কমিটসহ)'], ['Manifest: row counts and checksums', 'তালিকা: সারি আর চেকসাম']].map(function(x){ return '<div class="a2-rule">' + a2i('check', 14) + '<span>' + Le(x[0], x[1]) + '</span></div>'; }).join(''));
