ACT['a2b-bknow'] = function(){ var B = a2bBk(); B.running = true; rerender(); a2bJob(L('Backup', 'ব্যাকআপ'), 2000, function(){ B.running = false; var t = Date.now(); B.runs.unshift({at:t, size:'2.42 GB', blob:'ok', drive:'ok', by:a2Who()}); B.runs = B.runs.slice(0, 12); B.last = {blob:t, drive:t}; a2S().ntf.unshift({id:'n' + t, lvl:'fyi', t:'Backup done (2.42 GB)', bn:'ব্যাকআপ হয়েছে', s:'Azure Blob + Google Drive', at:t, href:'/admin/settings/system'}); a2Log('Backup now by ' + a2Who()); toast(L('Backup done', 'ব্যাকআপ হয়েছে')); }); };
ACT['a2b-restore'] = function(){ var B = a2bBk(); a2Confirm({title:'Restore a backup', bn:'ব্যাকআপ ফেরান', wide:true, body:'<div class="a2-fg"><div class="a2-fld full"><label class="a2-lbl" for="a2b-rb">' + Le('Backup', 'ব্যাকআপ') + '</label><select id="a2b-rb" class="a2-sel" data-f="b">' + B.runs.map(function(r, i){ return '<option value="' + i + '">' + esc(a2dt(r.at) + ' · ' + r.size) + '</option>'; }).join('') + '</select></div><div class="a2-fld full"><label class="a2-lbl" for="a2b-rt2">' + Le('Restore into', 'কোথায় ফেরাবেন') + '</label><select id="a2b-rt2" class="a2-sel" data-f="t"><option value="staging">' + Le('Staging copy first (safe)', 'আগে স্টেজিং কপিতে (নিরাপদ)') + '</option><option value="prod">' + Le('Production (the live shop)', 'আসল দোকান') + '</option></select></div><div class="a2-fld full"><label class="a2-lbl" for="a2b-rc">' + Le('For production, type RESTORE', 'আসল দোকানে ফেরাতে RESTORE লিখুন') + '</label><input id="a2b-rc" class="a2-inp" data-f="c" autocomplete="off"></div></div>', effects:[L('A safety copy of today is taken first', 'আগে আজকের একটা নিরাপত্তা কপি'), L('Staging: the live shop is untouched', 'স্টেজিং: আসল দোকানে হাত পড়ে না'), L('Production: the shop shows “back soon” for a few minutes', 'আসল দোকান: কয়েক মিনিট “শিগগির ফিরছি”')], reason:true, tone:'badf', ok:'Restore', okBn:'ফেরান',
  fn:function(r, f){ if(f.t === 'prod' && String(f.c).trim() !== 'RESTORE') return toast(L('Not restored — type RESTORE for production', 'ফেরানো হয়নি — RESTORE লিখুন')); a2bJob(L('Restoring into ', 'ফেরানো হচ্ছে: ') + (f.t === 'prod' ? 'production' : 'staging'), 1800, function(){ a2Log('Restore of backup ' + a2dt(B.runs[+f.b].at) + ' into ' + f.t + ' — ' + r); toast(f.t === 'prod' ? L('Demo: production restore simulated', 'ডেমো: আসল দোকানে ফেরানো দেখানো হলো') : L('Restored into staging — check it, then decide', 'স্টেজিংয়ে ফেরানো হয়েছে')); }); }}); };

